package org.jarvisassistant.app;
import android.app.*;
import android.os.*;
import android.view.*;
import android.webkit.CookieManager;
import android.widget.*;
import java.util.concurrent.*;

public final class CompanionSetupActivity extends Activity {
    private final ExecutorService worker=Executors.newSingleThreadExecutor();private TextView status;private Button connect;private EditText name;private String origin;private boolean active;private CompanionClient client;
    @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);LinearLayout root=NativeStyle.surface(this);root.addView(NativeStyle.toolbar(this,"Companion access","Your device, your choice",this::finish));ScrollView scroll=new ScrollView(this);LinearLayout body=NativeStyle.column(this);int p=NativeStyle.dp(this,24);body.setPadding(p,p,p,p);scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));body.addView(NativeStyle.title(this,"A voice that stays with you.",27));NativeStyle.gap(body,16);body.addView(NativeStyle.text(this,"Connect once for general JARVIS conversation while Android is locked. Camera check-ins are separate: you must turn them on in pet mode, and they stop when pet mode closes.\n\nThis key cannot access personal records, files, Windows sign-in or action approvals. You can disconnect it from Devices on your laptop.",15,NativeStyle.MUTED));NativeStyle.gap(body,24);name=new EditText(this);NativeStyle.input(this,name);name.setSingleLine(true);name.setText(Build.MODEL);name.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(60)});body.addView(name);NativeStyle.gap(body,16);status=NativeStyle.text(this,"Unlock your primary JARVIS workspace in the app before connecting.",13,NativeStyle.MUTED);body.addView(status);NativeStyle.gap(body,18);connect=NativeStyle.action(this,"Connect this companion","connection",true,this::connect);body.addView(connect);try{origin=EndpointPolicy.connection(getIntent().getStringExtra("origin"));if(CompanionClient.enrolled(this,origin))status.setText("A companion key is saved on this phone. Connecting again requires an unlocked primary workspace.");}catch(Exception error){connect.setEnabled(false);status.setText("Connect this phone to JARVIS first.");}}
    private void connect(){String label=name.getText().toString().trim();if(label.isEmpty()){name.setError("Give this device a name");return;}connect.setEnabled(false);status.setText("Connecting to your private JARVIS host…");String cookie=CookieManager.getInstance().getCookie(origin);worker.execute(()->{String error=null;try(CompanionClient value=new CompanionClient(this,origin)){client=value;value.enroll(cookie,label);}catch(Exception failed){error=failed instanceof java.io.IOException?failed.getMessage():"Companion access could not be connected. Unlock JARVIS in the app and try again.";}finally{client=null;}String problem=error;runOnUiThread(()->{if(!active)return;connect.setEnabled(true);status.setText(problem==null?"Connected. General voice is ready; camera sharing stays off until you choose it.":problem);if(problem==null)connect.setText("Reconnect companion");});});}
    @Override protected void onResume(){super.onResume();active=true;}
    @Override protected void onPause(){active=false;if(client!=null)client.close();super.onPause();}
    @Override protected void onDestroy(){worker.shutdownNow();super.onDestroy();}
}
